<?php declare(strict_types=1); namespace App\Http\Requests\Admin; use App\Support\PermissionCatalog; use Illuminate\Foundation\Http\FormRequest; use Illuminate\Validation\Rule; final class RoleRequest extends FormRequest { public function authorize(): bool { return true; } public function rules(): array { return ['name'=>['required','string','max:100',Rule::unique('roles','name')->ignore($this->route('id'))],'permissions'=>['sometimes','array'],'permissions.*'=>['string',Rule::in(PermissionCatalog::allNames())]]; }}